//! Telemetry-only scheduling lives in the destination's existing progress ledger.
//! Bodies are regenerated by the ordinary evidence chunk, never kept in an outbox.
use super::*;
use crate::claude_local_otel::{self as otel, TelemetryGeneration};
use time::{format_description::well_known::Rfc3339, OffsetDateTime};

pub(super) const CONTRACT: &str = "claude_otel_only_sessions:v1";
#[derive(Clone, Copy)]
pub(super) struct Window {
    floor: i128,
    ceiling: Option<i128>,
    start: i128,
}
fn clock(value: &str) -> Option<i128> {
    OffsetDateTime::parse(value, &Rfc3339)
        .ok()
        .map(|t| t.unix_timestamp_nanos())
}
const SLACK: i128 = 300_000_000_000;
pub(super) fn advertised(hint: &crate::snapshot_client::ActivityHintResponse) -> Option<Window> {
    if hint.source != "claude_code"
        || !hint.local_usage_reconciliation_enabled
        || !hint.snapshot_head_cas_required
        || hint.claude_otel_only_sessions_contract.as_deref() != Some(CONTRACT)
    {
        return None;
    }
    let floor = clock(hint.claude_otel_only_pairing_floor.as_deref()?)?;
    let ceiling = match hint.claude_otel_only_pairing_ceiling.as_deref() {
        Some(value) => Some(clock(value)?),
        None => None,
    };
    if ceiling.is_some_and(|end| end <= floor + 2 * SLACK) {
        return None;
    }
    Some(Window {
        floor,
        ceiling,
        start: floor + SLACK,
    })
}
#[derive(Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub(super) struct Ledger {
    floor: i128,
    start: i128,
    #[serde(default)]
    candidates: BTreeMap<String, Candidate>,
}
#[derive(Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
struct Candidate {
    #[serde(default, skip_serializing_if = "Option::is_none")]
    built: Option<Binding>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    accepted: Option<Binding>,
    /// Last healthy refused generation; unchanged pre-activation bytes are not re-read.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    observed: Option<TelemetryGeneration>,
    #[serde(skip)]
    reading: Option<TelemetryGeneration>,
    #[serde(skip, default = "default_true")]
    inspect: bool,
}
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize)]
struct Binding {
    fingerprint: String,
    body: String,
    generation: TelemetryGeneration,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    context: Option<String>,
}
fn default_true() -> bool {
    true
}
impl std::fmt::Debug for Ledger {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("TelemetryCandidates")
            .field("count", &self.candidates.len())
            .finish()
    }
}
crate::heap_layout_bound::fields!(Ledger; floor, start, candidates);
crate::heap_layout_bound::fields!(Candidate; built, accepted, observed, reading, inspect);
crate::heap_layout_bound::fields!(Binding; fingerprint, body, generation, context);

impl Ledger {
    pub(super) fn references(&self) -> impl Iterator<Item = &str> {
        self.candidates
            .values()
            .flat_map(|c| c.built.iter().chain(c.accepted.iter()))
            .map(|b| b.fingerprint.as_str())
    }
}

impl SnapshotUploadProgress {
    /// Shared across the whole ACK-retirement owner, including capacity and recovery.
    pub(super) fn ack_incidence<'a>(
        &'a self,
        index: &'a ScanIndex,
    ) -> impl Iterator<Item = &'a str> {
        index.upload_progress_ack_incidence().chain(
            self.telemetry_only
                .iter()
                .flat_map(|ledger| ledger.candidates.values())
                .flat_map(|candidate| candidate.built.iter().chain(candidate.accepted.iter()))
                .map(|binding| binding.fingerprint.as_str()),
        )
    }

    pub(super) fn seed_telemetry(
        &mut self,
        support: &Path,
        hint: &crate::snapshot_client::ActivityHintResponse,
        scan: &mut SourceScanResult,
        index: &ScanIndex,
        progress_path: &Path,
    ) -> Result<Option<Window>> {
        let Some(mut window) = advertised(hint) else {
            otel::telemetry_notices::configure(support, false)?;
            return Ok(None);
        };
        let fresh = self
            .telemetry_only
            .as_ref()
            .is_none_or(|ledger| ledger.floor != window.floor);
        if fresh {
            let ledger = self.telemetry_only.get_or_insert_with(Default::default);
            ledger.floor = window.floor;
            ledger.start = OffsetDateTime::now_utc()
                .unix_timestamp_nanos()
                .max(window.start);
            self.save(progress_path)?;
        }
        window.start = self
            .telemetry_only
            .as_ref()
            .expect("activated ledger")
            .start;
        otel::telemetry_notices::configure(support, true)?;
        let batch = otel::telemetry_notices::detach(support)?;
        if !batch.roots.is_empty() {
            let ledger = self.telemetry_only.as_mut().expect("activated ledger");
            for root in &batch.roots {
                ledger.candidates.entry(root.clone()).or_default().inspect = true;
            }
            self.save(progress_path)?;
        }
        batch.committed();
        // Page facts are captured before any synthetic slot exists. An all-copy
        // page still has a transcript, even when later normalization emits none.
        let page_roots = claude_evidence_session_ids(&scan.snapshots)
            .into_iter()
            .collect::<BTreeSet<_>>();
        let candidates = self
            .telemetry_only
            .as_ref()
            .expect("activated ledger")
            .candidates
            .keys()
            .cloned()
            .collect();
        let absent =
            crate::snapshots::claude_request_money::e2::telemetry_roots_absent(index, &candidates);
        let mut examined = Vec::new();
        let mut selected = Vec::new();
        for (root, candidate) in &self
            .telemetry_only
            .as_ref()
            .expect("activated ledger")
            .candidates
        {
            if page_roots.contains(root) || !absent.contains(root) {
                continue;
            }
            let due = candidate
                .built
                .as_ref()
                .is_some_and(|b| !self.contains_body(&b.fingerprint, &b.body));
            if !candidate.inspect && !due {
                continue;
            }
            let Ok(generation) = otel::telemetry_generation(support, root) else {
                continue;
            };
            if generation.iter().any(Option::is_none) {
                continue;
            }
            let unchanged = candidate.built.as_ref().is_some_and(|b| {
                b.generation == generation && self.contains_body(&b.fingerprint, &b.body)
            });
            if unchanged {
                examined.push(root.clone());
                continue;
            }
            if !due && candidate.observed.as_ref() == Some(&generation) {
                continue;
            }
            selected.push((root.clone(), generation));
        }
        let ledger = self.telemetry_only.as_mut().expect("activated ledger");
        for root in examined {
            ledger
                .candidates
                .get_mut(&root)
                .expect("examined candidate")
                .inspect = false;
        }
        for (root, generation) in selected {
            let candidate = ledger
                .candidates
                .get_mut(&root)
                .expect("selected candidate");
            candidate.observed = Some(generation.clone());
            candidate.reading = Some(generation);
            scan.snapshots
                .push(SnapshotItem::neutral_telemetry(root, current_rfc3339()));
        }
        Ok(Some(window))
    }

    /// Called after ordinary policy/finalization, before upload. The generations
    /// captured before strict decode must still match; no ACK-time stat mints proof.
    pub(super) fn bind_telemetry_bodies(&mut self, support: &Path, items: &mut Vec<SnapshotItem>) {
        let context = self.context_resend.active.clone();
        let Some(ledger) = self.telemetry_only.as_mut() else {
            return;
        };
        items.retain(|item| {
            if item.evidence_basis != Some("otel_only") {
                return true;
            }
            let Some(candidate) = ledger.candidates.get_mut(&item.source_session_id) else {
                return false;
            };
            let Some(generation) = candidate.reading.take() else {
                return false;
            };
            if otel::telemetry_generation(support, &item.source_session_id)
                .ok()
                .as_ref()
                != Some(&generation)
            {
                candidate.inspect = true;
                return false;
            }
            candidate.observed = Some(generation.clone());
            candidate.built = Some(Binding {
                fingerprint: item.snapshot_fingerprint.clone(),
                body: snapshot_upload_body_witness(item),
                generation,
                context: context.clone(),
            });
            true
        });
    }

    pub(super) fn accept_telemetry(&mut self, root: &str, fingerprint: &str, body: &str) {
        let Some(candidate) = self
            .telemetry_only
            .as_mut()
            .and_then(|l| l.candidates.get_mut(root))
        else {
            return;
        };
        if let Some(built) = candidate
            .built
            .as_ref()
            .filter(|built| built.fingerprint == fingerprint && built.body == body)
        {
            candidate.accepted = Some(built.clone());
        }
    }

    pub(super) fn committed_telemetry_deliveries(
        &self,
        index_path: &Path,
        path: &Path,
    ) -> Result<BTreeMap<String, TelemetryGeneration>> {
        if self.telemetry_only.is_none() {
            return Ok(BTreeMap::new());
        }
        let committed: Self = if self.rows.is_some() {
            let owner = SnapshotProgressLock::acquire(path)?.for_v2(path);
            let (ledger, generation) = crate::snapshots::read_progress_ledger(index_path, &owner)?;
            anyhow::ensure!(
                generation > 0,
                "telemetry delivery requires committed progress"
            );
            serde_json::from_value(ledger.context("missing committed progress ledger")?)?
        } else {
            serde_json::from_slice(&std::fs::read(path)?)?
        };
        anyhow::ensure!(
            committed.destination_namespace_hash == self.destination_namespace_hash,
            "telemetry delivery destination changed"
        );
        Ok(committed.telemetry_deliveries())
    }

    pub(super) fn retire_telemetry_candidates(&mut self, retired: &BTreeSet<String>) {
        if let Some(ledger) = self.telemetry_only.as_mut() {
            ledger
                .candidates
                .retain(|root, _| !retired.contains(&otel::telemetry_stem(root)));
        }
    }

    /// Call on a freshly loaded committed ledger. Uncommitted RAM ACKs are
    /// never authority, even if a later graph save succeeds.
    pub(super) fn telemetry_deliveries(&self) -> BTreeMap<String, TelemetryGeneration> {
        self.telemetry_only
            .iter()
            .flat_map(|l| &l.candidates)
            .filter_map(|(root, candidate)| {
                let accepted = candidate.accepted.as_ref()?;
                (self.accepted_body_witnesses.get(&accepted.fingerprint) == Some(&accepted.body)
                    && self.accepted_body_contexts.get(&accepted.fingerprint)
                        == accepted.context.as_ref())
                .then(|| (otel::telemetry_stem(root), accepted.generation.clone()))
            })
            .collect()
    }
}

/// Called inside the ordinary evidence chunk with its already-strict loaded rows.
pub(super) fn build(
    mut item: SnapshotItem,
    api: &otel::ClaudeLocalOtelLoadReport,
    trace: &otel::ClaudeTraceOwnershipLoadReport,
    index: &ScanIndex,
    window: Window,
    accepted: Option<&crate::snapshots::claude_request_identity::AcceptedBuckets>,
    budget: crate::snapshots::claude_request_identity::WireBudget<'_>,
) -> Option<SnapshotItem> {
    use crate::snapshots::{
        claude_request_census, claude_request_identity, claude_request_money::e2,
    };
    let root = item.source_session_id.as_str();
    let rows = api.evidence.get(root)?;
    let mut unique = BTreeMap::new();
    for row in rows {
        if unique
            .insert(row.request_id.as_str(), row)
            .is_some_and(|old: &otel::ClaudeLocalOtelEvidence| old.fingerprint != row.fingerprint)
        {
            return None;
        }
    }
    if unique.is_empty() {
        return None;
    }
    let traces = trace.evidence.get(root)?;
    let trace_ids = traces
        .iter()
        .map(|row| row.request_id.as_str())
        .collect::<BTreeSet<_>>();
    if trace_ids != unique.keys().copied().collect() {
        return None;
    }
    if traces
        .iter()
        .any(|row| !crate::snapshots::claude_trace_evidence_fingerprint_is_valid(row))
    {
        return None;
    }
    let wanted = unique
        .keys()
        .map(|id| claude_request_census::claude_request_hash(id))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>();
    let held = claude_request_census::positive_holders(&index.claude_request_census, &wanted);
    let mut entity = e2::ClaudeEntityBody::default();
    let mut first = i128::MAX;
    let mut last = i128::MIN;
    for row in unique.values() {
        let at = clock(&row.observed_at)?;
        // Never turn an old root's post-activation suffix into a fresh session.
        if at <= window.start
            || at <= window.floor + SLACK
            || window.ceiling.is_some_and(|end| at >= end - SLACK)
        {
            return None;
        }
        if held.contains(&claude_request_census::claude_request_hash(&row.request_id)) {
            continue;
        }
        if row.request_count != 1
            || row.session_id.as_ref() != root
            || !crate::snapshots::claude_api_evidence_fingerprint_is_valid(row)
        {
            return None;
        }
        e2::add_reported_row(
            &mut entity,
            row,
            claude_request_identity::side_call_account(row, root),
            None,
        )?;
        first = first.min(at);
        last = last.max(at);
    }
    if entity.grains.is_empty() {
        return None;
    }
    entity.telemetry_owned_complete = true;
    let format = |at| {
        OffsetDateTime::from_unix_timestamp_nanos(at)
            .ok()?
            .format(&Rfc3339)
            .ok()
    };
    item.source_started_at = format(first);
    item.source_last_activity_at = format(last);
    if !e2::emit_entity(&mut item, &entity)
        || !claude_request_identity::tag_telemetry_entity(&mut item, &entity, accepted, budget)
    {
        return None;
    }
    Some(item)
}

